export type WrappedCardKind = "magicYear" | "banned" | "yearInNumbers" | "formats" | "whenYouPlay" | "deckOfYear" | "bestDeck" | "mvpCard" | "openingHand" | "sideboardHero" | "mostFaced" | "bestMatchup" | "toughestRival" | "comebacks" | "playDraw" | "trophies" | "limited" | "playerType" | "wrap";

/**  What the Wrapped page and the dashboard card read. */
export type WrappedState = {
	/**  The Wrapped year shown now; `None` outside December. */
	year: number | null,
	/**  The player closed this year's dashboard card. */
	dismissed: boolean,
	/**
	 *  This year's bundle; `None` below the 30-match floor, and always
	 *  `None` when `year` is.
	 */
	bundle: WrappedBundle | null,
};

export type YearInNumbersCard = {
	matches: number,
	games: number,
	hours: number,
	daysPlayed: number,
	/**
	 *  Matches started on each local day of the counted year, 1 January
	 *  first, one entry per day up to 30 November: the card's activity grid.
	 */
	byDay: number[],
	/**
	 *  The player's place among MyMTGO players by matches played, as a
	 *  "top N%" (1 to 100). Set from the API's percentiles (phase 4); the
	 *  card only shows it when it is 50 or less.
	 */
	topPercent: number | null,
};

/**
 *  The counted year: from 1 January (inclusive) to 1 December (exclusive),
 *  local midnights, as UTC milliseconds.
 */
export type YearWindow = {
	startMs: number,
	endMs: number,
};

export type ZoneDiffView = {
	added: CardQuantityView[],
	removed: CardQuantityView[],
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

